import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def calculate_x_k(k, n):
    if n == 0:
        return 1 # Or handle as error, but n is a positive integer
    if n == 1:
        return k

    current_lcm = k
    for i in range(k + 1, k + n):
        current_lcm = lcm(current_lcm, i)
    return current_lcm

# Test setup
N_values = [1, 2, 3, 4, 5]
K_limit = 20
results = {}

for n in N_values:
    x_values = {}
    # Calculate x_k for k=1 up to K_limit+1 (we need x_{k+1})
    for k in range(1, K_limit + 2):
        x_values[k] = calculate_x_k(k, n)

    increasing_test = []
    is_strictly_increasing_up_to_20 = True

    # Check x_{k+1} > x_k for k=1 up to 20
    for k in range(1, K_limit + 1):
        x_k = x_values[k]
        x_k_plus_1 = x_values[k+1]

        comparison = "x_{k+1} > x_k" if x_k_plus_1 > x_k else "x_{k+1} <= x_k"
        increasing_test.append(f"k={k}: {comparison}")

        if x_k_plus_1 <= x_k:
            is_strictly_increasing_up_to_20 = False

    results[n] = {
        "is_strictly_increasing_up_to_20": is_strictly_increasing_up_to_20,
        "tests": increasing_test
    }

# Output results in a readable format for notes.md
print("--- Test Results ---")
for n, data in results.items():
    print(f"\n--- N = {n} ---")
    print(f"Is strictly increasing up to k=20? {data['is_strictly_increasing_up_to_20']}")

    # Print a sample of the comparison results
    print("First 5 comparisons (k=1 to 5):")
    for i in range(min(5, len(data['tests']))):
        print(data['tests'][i])

    if not data['is_strictly_increasing_up_to_20']:
        print("Check failed somewhere in k=1 to 20.")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def calculate_xk(k, n):
    if n == 1:
        return k
    if n == 2:
        return lcm(k, k + 1)
    # This function is only needed for n=1 and n=2 as per the task
    return -1

print("--- Testing N=1 ---")
failures_n1 = False
for k in range(1, 101):
    x_k = calculate_xk(k, 1)
    x_k_plus_1 = calculate_xk(k + 1, 1)
    if x_k_plus_1 <= x_k:
        print(f"Failure found for N=1 at k={k}: x_{k+1} ({x_k_plus_1}) <= x_k ({x_k})")
        failures_n1 = True
        break

if not failures_n1:
    print("N=1 confirmed: x_{k+1} > x_k for k=1 to 100.")

print("\n--- Testing N=2 ---")
failures_n2 = False
for k in range(1, 101):
